cd /data; mkdir -p /out; cat > /tmp/q.sql <<'E'
WITH e AS (
 SELECT e.*, COALESCE(d.name,'(none)') AS dname FROM employees e LEFT JOIN departments d ON d.id=e.dept_id
), names AS (
 SELECT name AS dname FROM departments UNION SELECT '(none)' WHERE EXISTS (SELECT 1 FROM e WHERE dname='(none)' AND dept_id IS NOT d_dummy)
)
SELECT 1;
E
sqlite3 hr.db "select * from employees"

